CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_CAPEX_SPEND_MONTH_ACCOUNT_NAME_COST_CENTER
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_CAPEX_SPEND at grain Date.FiscalYear, Date.MonthName, Date.Quarter, GLAccount.AccountName, GLAccount.CostCenter, Date.MonthNumber; covers 35.84% of weighted demand (1 clusters); est. 300,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       g2.ACCOUNT_NAME,
       g2.COST_CENTER,
       d1.MONTH_NUMBER,
       SUM(f.SPENT_TO_DATE) AS SPENT_TO_DATE,
       COUNT(*) AS CAPEX_SPEND_COUNT
FROM CORE.FCT_CAPEX_SPEND f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_GL_ACCOUNT g2 ON f.GL_ACCOUNT_ID = g2.GL_ACCOUNT_ID
GROUP BY ALL;
